import ThankYouPanel from '../components/ThankYouPanel'
import { BOOK, CALL } from '../content/treatments/ctas'

/**
 * /thank-you-lp/ -- the ad funnel's confirmation step.
 *
 * NO GENERATED MARKER, DELIBERATELY. scripts/gen-pages.mjs overwrites any page
 * file still carrying `// GENERATED by scripts/gen-pages.mjs`.
 *
 * ONE OF THE SIX noindex AD LANDING PAGES. It carries no canonical and is not
 * in the sitemap; scripts/verify-seo.mjs asserts both, so nothing here may
 * touch src/seo/pages.ts or src/seo/schema/thank-you-lp.json.
 *
 * NOT IN THE NAV, DELIBERATELY. It is reached only by converting on an ad
 * landing page. Adding it to src/config/nav.ts would change the captured
 * header/footer that verify-seo check 8 walks.
 *
 * COPY: neofollicle-seo-backup/pages/thank-you-lp/ -- the capture's three
 * headings, verbatim. The capture has no h1 at all (seoFor('thank-you-lp').h1
 * is null), so "Thank You" is promoted from its h3 to be the page's one h1.
 */
export default function ThankYouLp() {
  return (
    <ThankYouPanel
      heading="Thank You"
      lines={['Your Hair Analysis Report should reach your email in 2 - 3 minutes.']}
      note="One of our team members will contact you shortly."
      ctas={[CALL, BOOK]}
    />
  )
}
